#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "cholesky.h"


/* Array initialization.
 *
 * Optimizations:
 *  - Use row pointers (unit-stride accesses) to improve cache locality.
 *  - Express the "make positive semi-definite" step as B = A * A^T
 *    with (r,s,t) loop order so the innermost loop is a simple dot
 *    product (good for vectorization).
 *  - Remove the redundant zero-initialization of B: each B[r][s]
 *    is fully overwritten by a fresh dot product.
 *  - Add OpenMP parallelization on the outer row loops (when enabled
 *    at compile time via -fopenmp). Each row is independent, so this
 *    does not change the numerical order of operations for any
 *    individual matrix element.
 */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Initialize A as in the original code: a lower-triangular
     matrix with ones on the diagonal.  Each iteration of the
     outer loop touches a distinct row, so it is safe to
     parallelize. */
#pragma omp parallel for private(j) schedule(static) if (n >= 64)
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict Ai = A[i];

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / (DATA_TYPE)n + (DATA_TYPE)1;

      for (j = i+1; j < n; j++)
	Ai[j] = (DATA_TYPE)0;

      Ai[i] = (DATA_TYPE)1;
    }

  /* Make the matrix positive semi-definite: A <- A * A^T. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Compute B = A * A^T.
   *
   * For each (r,s) pair we compute a dot product of row r and row s:
   *   B[r][s] = sum_t A[r][t] * A[s][t].
   *
   * The innermost loop iterates over t, giving unit-stride access
   * to both A[r][t] and A[s][t], which is cache-friendly and
   * vectorization-friendly.  Each (r,s) pair is independent, so
   * the outer loop over r is parallelizable.
   *
   * For a fixed (r,s), the sequence of floating-point operations on
   * that element is the same as in the original code (accumulation
   * over t in increasing order), so numerical behavior is preserved
   * up to usual floating-point round-off.
   */
#pragma omp parallel for private(s,t) schedule(static) if (n >= 16)
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict Ar = A[r];

      for (s = 0; s < n; ++s)
        {
          DATA_TYPE *restrict As = A[s];
          DATA_TYPE acc = (DATA_TYPE)0;

          for (t = 0; t < n; ++t)
            acc += Ar[t] * As[t];

          (POLYBENCH_ARRAY(B))[r][s] = acc;
        }
    }

  /* Copy B back into A.  Row-wise traversal ensures unit-stride
     accesses for both read and write.  Rows are independent, so
     this copy can also be parallelized. */
#pragma omp parallel for private(s) schedule(static) if (n >= 64)
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict Ar = A[r];
      DATA_TYPE *restrict Br = (POLYBENCH_ARRAY(B))[r];

      for (s = 0; s < n; ++s)
	Ar[s] = Br[s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *Ai = A[i];
      for (j = 0; j <= i; j++) {
        if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
        fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, Ai[j]);
      }
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *  - Use row pointers (Ai, Aj) so that repeated accesses to A[i][*]
 *    and A[j][*] hit cached, unit-stride memory rather than going
 *    through 2D indexing each time.
 *  - Keep the recurrence over k in registers (val, diag) instead of
 *    repeatedly loading/storing A[i][j] and A[i][i].  This preserves
 *    the order of floating-point operations for each element while
 *    greatly reducing memory traffic.
 *  - All algorithmic dependencies are preserved: neither the i-loop
 *    nor the j-loop is parallelized since each iteration depends on
 *    previously computed elements of A.
 */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
     /* Row pointer for the current row i. */
     DATA_TYPE *restrict Ai = A[i];

     /* Off-diagonal elements (strictly lower triangular part). */
     for (j = 0; j < i; j++) {
        DATA_TYPE *restrict Aj = A[j];

        /* Original code:
             for (k = 0; k < j; k++)
               A[i][j] -= A[i][k] * A[j][k];
           We keep the same recurrence, but perform it on a
           register-resident scalar 'val' to avoid repeated
           memory loads/stores of A[i][j]. */
        DATA_TYPE val = Ai[j];

        for (k = 0; k < j; k++) {
           val -= Ai[k] * Aj[k];
        }

        /* Divide by the diagonal element A[j][j]. */
        val /= Aj[j];
        Ai[j] = val;
     }

     /* Diagonal element A[i][i].  Again, we use a scalar accumulator
        to keep the update in registers while preserving the original
        recurrence:
          for (k = 0; k < i; k++)
            A[i][i] -= A[i][k] * A[i][k]; */
     DATA_TYPE diag = Ai[i];
     for (k = 0; k < i; k++) {
        DATA_TYPE aik = Ai[k];
        diag -= aik * aik;
     }
     Ai[i] = SQRT_FUN(diag);
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
