#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "cholesky.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Create a local restrict-qualified view of A to help the compiler
     with alias analysis and enable better optimization. */
  DATA_TYPE (* __restrict Aview)[n] = A;

  /* Initial lower-triangular matrix. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE * __restrict Ai = Aview[i];

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	Ai[j] = 0;
      }
      Ai[i] = 1;
    }

  /* Make the matrix positive semi-definite.
     We form B = A * A^T (a Gram matrix), then copy B back into A. */
  int r, s;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Local restrict-qualified views for better optimization. */
  DATA_TYPE (* __restrict Bview)[n] = POLYBENCH_ARRAY(B);
  DATA_TYPE (* __restrict Aview2)[n] = Aview;

  /* Compute B = A * A^T.
     Each (r,s) pair is independent; the inner loop over t preserves
     the original computation order for each B[r][s].  This improves
     cache locality compared to the original t–r–s ordering, because
     rows of A are accessed contiguously. */
#pragma omp parallel for collapse(2) schedule(static) if (n >= 128)
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      {
        DATA_TYPE sum = (DATA_TYPE)0;
        for (int t = 0; t < n; ++t)
          sum += Aview2[r][t] * Aview2[s][t];
        Bview[r][s] = sum;
      }

  /* Copy B back into A (row-major order, cache-friendly). */
#pragma omp parallel for collapse(2) schedule(static) if (n >= 128)
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      Aview[r][s] = Bview[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j <= i; j++) {
    if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
  }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   This is an in-place Cholesky factorization of a symmetric
   positive-definite matrix, computing a lower-triangular factor.
*/
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Restrict-qualified row-major view of A.
     This helps the compiler keep frequently-used row pointers and
     elements in registers, and improves alias analysis. */
  DATA_TYPE (* __restrict Aview)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
     DATA_TYPE * __restrict Ai = Aview[i];

     /* Off-diagonal elements in row i: columns 0 .. i-1 */
     for (j = 0; j < i; j++) {
        DATA_TYPE * __restrict Aj = Aview[j];

        /* Use a local accumulator for A[i][j] to reduce memory traffic.
           The update order over k is identical to the original code:
             A[i][j]_{k+1} = A[i][j]_k - A[i][k]*A[j][k]
           so floating-point semantics are preserved. */
        DATA_TYPE tmp = Ai[j];
        for (k = 0; k < j; k++) {
           tmp -= Ai[k] * Aj[k];
        }
        tmp /= Aj[j];   /* divide by diagonal A[j][j] */
        Ai[j] = tmp;
     }

     /* Diagonal element A[i][i] */
     DATA_TYPE diag = Ai[i];
     for (k = 0; k < i; k++) {
        DATA_TYPE aik = Ai[k];
        diag -= aik * aik;
     }
     Ai[i] = SQRT_FUN(diag);
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
