   * - lower triangular with some pattern below the diagonal
   * - zero above the diagonal
   * - unit diagonal
   *
   * Use a row pointer to improve spatial locality and reduce
   * address arithmetic inside the loops.
   */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict Ai = A[i];

      for (j = 0; j <= i; j++)
        /* (-j % n) == -(j % n) for positive n and j, but the latter
         * is slightly clearer.  Cast both numerator and denominator
         * to DATA_TYPE to keep all arithmetic in the target precision.
         */
	Ai[j] = (DATA_TYPE)(-(j % n)) / (DATA_TYPE)n + (DATA_TYPE)1;

      for (j = i+1; j < n; j++)
	Ai[j] = (DATA_TYPE)0;

      Ai[i] = (DATA_TYPE)1;
    }

  /* Make the matrix positive semi-definite:
   *   B = A * A^T
   * then copy B back into A.
   *
   * The computation is reorganized to improve cache locality:
   *  - B is accessed in contiguous rows;
   *  - the (r,s) index space is processed in tiles;
   *  - for each (r,s), the accumulation over t is still carried
   *    out in increasing order of t, so the scalar recurrence
   *    for B[r][s] matches the original algorithm up to the usual
   *    floating-point round-off.
   *
   * OpenMP pragmas are added for parallel zeroing, SPD construction
   * and copying.  If compiled without -fopenmp, these pragmas are
   * ignored by the compiler and the code remains correct and
   * single-threaded.
   */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);

  /* Zero-initialize B. */
#pragma omp parallel for if (n >= 64) private(s) schedule(static)
  for (r = 0; r < n; ++r)
  {
    DATA_TYPE *restrict Br = B_[r];
    for (s = 0; s < n; ++s)
      Br[s] = (DATA_TYPE)0;
  }

  const int TILE = INIT_ARRAY_TILE;

  /* Blocked computation of B = A * A^T.
   *
   * Original:
   *   for (t = 0; t < n; ++t)
   *     for (r = 0; r < n; ++r)
   *       for (s = 0; s < n; ++s)
   *         B[r][s] += A[r][t] * A[s][t];
   *
   * New:
   *   for (rr in tiles of rows)
   *     for (ss in tiles of columns)
   *       for (t)
   *         for (r in tile rr)
   *           for (s in tile ss)
   *             B[r][s] += A[r][t] * A[s][t];
   *
   * For a fixed pair (r,s), the sequence of updates over t is still
   * performed in t = 0,1,...,n-1 order, preserving the scalar
   * recurrence for B[r][s].
   */
#pragma omp parallel for collapse(2) private(r,s,t) schedule(static) if (n >= 64)
  for (int rr = 0; rr < n; rr += TILE)
  {
    for (int ss = 0; ss < n; ss += TILE)
    {
      int r_max = rr + TILE;
      if (r_max > n) r_max = n;
      int s_max = ss + TILE;
      if (s_max > n) s_max = n;

      for (t = 0; t < n; ++t)
      {
        for (r = rr; r < r_max; ++r)
        {
          DATA_TYPE *restrict Br = B_[r];
          const DATA_TYPE A_rt = A[r][t];

          for (s = ss; s < s_max; ++s)
          {
            Br[s] += A_rt * A[s][t];
          }
        }
      }
    }
  }

  /* Copy B back into A. */
#pragma omp parallel for if (n >= 64) private(s) schedule(static)
  for (r = 0; r < n; ++r)
  {
    DATA_TYPE *restrict Ar = A[r];
    DATA_TYPE *restrict Br = B_[r];

    for (s = 0; s < n; ++s)
      Ar[s] = Br[s];
  }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j <= i; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++)
  {
    /* Pointer to the current row. Using a row pointer improves data
     * locality and reduces index arithmetic inside inner loops. */
    DATA_TYPE *restrict Ai = A[i];

    /* Compute the off-diagonal entries in row i: j < i.
     *
     * Original code:
     *   for (j = 0; j < i; j++) {
     *     for (k = 0; k < j; k++)
     *       A[i][j] -= A[i][k] * A[j][k];
     *     A[i][j] /= A[j][j];
     *   }
     *
     * This is mathematically equivalent to:
     *   tmp = A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[j][k];
     *   A[i][j] = tmp / A[j][j];
     *
     * We compute the dot product first (sum) and apply the update once.
     * This reduces memory traffic for A[i][j] and exposes a clean
     * dot-product pattern that vectorizers can exploit. The change only
     * affects floating-point rounding at the level of associativity.
     */
    for (j = 0; j < i; j++)
    {
      DATA_TYPE *restrict Aj = A[j];
      DATA_TYPE sum = (DATA_TYPE)0;

#pragma GCC ivdep
#pragma omp simd reduction(+:sum)
      for (k = 0; k < j; k++)
      {
        sum += Ai[k] * Aj[k];
      }

      Ai[j] = (Ai[j] - sum) / Aj[j];
    }

    /* Diagonal element:
     *
     * Original code:
     *   for (k = 0; k < i; k++)
     *     A[i][i] -= A[i][k] * A[i][k];
     *   A[i][i] = SQRT_FUN(A[i][i]);
     *
     * We compute sum_{k=0}^{i-1} A[i][k]^2 first, then apply the
     * subtraction once.  Again, this reduces memory traffic on A[i][i]
     * and exposes a vectorizable reduction.
     */
    DATA_TYPE sum = (DATA_TYPE)0;

#pragma GCC ivdep
#pragma omp simd reduction(+:sum)
    for (k = 0; k < i; k++)
    {
      const DATA_TYPE aik = Ai[k];
      sum += aik * aik;
    }

    Ai[i] = SQRT_FUN(Ai[i] - sum);
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
