#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "cholesky.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Initialize A as a lower-triangular matrix with 1 on the diagonal.
   * Use row pointers to improve locality and reduce address arithmetic.
   */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE* Ai = A[i];

      /* Strictly lower-triangular part. */
      for (j = 0; j < i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + (DATA_TYPE)1;

      /* Diagonal.  The original code first set it via the formula and then
       * overwrote it with 1, so setting it only once to 1 is equivalent.
       */
      Ai[i] = (DATA_TYPE)1;

      /* Upper-triangular part is zero. */
      for (j = i+1; j < n; j++)
	Ai[j] = (DATA_TYPE)0;
    }

  /* Make the matrix positive semi-definite: B = A * A^T, then copy B into A.
   *
   * The loop order (t, r, s) is preserved exactly as in the original code
   * to keep floating‑point accumulation order identical.  Within that order,
   * we:
   *  - use a temporary for A[r][t] to avoid redundant loads,
   *  - use row pointers for B[r][*] to improve spatial locality.
   */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (*B_ptr)[n] = POLYBENCH_ARRAY(B);

  /* Zero B. */
  for (r = 0; r < n; ++r) {
    DATA_TYPE* restrict Br = B_ptr[r];
    for (s = 0; s < n; ++s)
      Br[s] = (DATA_TYPE)0;
  }

  /* B[r][s] += A[r][t] * A[s][t] */
  for (t = 0; t < n; ++t)
    for (r = 0; r < n; ++r)
      {
        DATA_TYPE* restrict Br = B_ptr[r];
        const DATA_TYPE Art = A[r][t]; /* common factor for this (r,t) */
        for (s = 0; s < n; ++s)
          Br[s] += Art * A[s][t];
      }

  /* Copy B back into A.  Using memcpy per row improves efficiency and
   * keeps the element-wise values identical to the original code.
   */
  for (r = 0; r < n; ++r) {
    DATA_TYPE* restrict Ar = A[r];
    DATA_TYPE* restrict Br = B_ptr[r];
    memcpy(Ar, Br, (size_t)n * sizeof(DATA_TYPE));
  }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      DATA_TYPE* Ai = A[i];
      for (j = 0; j <= i; j++) {
        if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
        fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, Ai[j]);
      }
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  /* Standard in-place Cholesky factorization (lower triangular).
   *
   * Optimizations:
   *  - Use row pointers (Ai, Aj) to improve cache locality and reduce
   *    address computations.
   *  - Accumulate each A[i][j] and A[i][i] into a scalar variable
   *    (aij / diag) inside the inner loops, then write back once.
   *    This avoids repeated memory loads/stores on the same element
   *    and keeps the arithmetic order identical to the original code.
   */
  for (i = 0; i < _PB_N; i++) {
     DATA_TYPE* restrict Ai = A[i];

     /* Off-diagonal elements in row i (j < i). */
     for (j = 0; j < i; j++) {
        DATA_TYPE* restrict Aj = A[j];

        /* Start from the original A[i][j] value. */
        DATA_TYPE aij = Ai[j];

        /* A[i][j] -= sum_{k=0}^{j-1} A[i][k] * A[j][k] */
        for (k = 0; k < j; k++) {
           aij -= Ai[k] * Aj[k];
        }

        /* Then divide by the diagonal element A[j][j]. */
        aij /= Aj[j];

        /* Write back once. */
        Ai[j] = aij;
     }

     /* Diagonal element A[i][i]. */
     DATA_TYPE diag = Ai[i];

     /* A[i][i] -= sum_{k=0}^{i-1} A[i][k]^2 */
     for (k = 0; k < i; k++) {
        const DATA_TYPE Aik = Ai[k];
        diag -= Aik * Aik;
     }

     /* Final square root. */
     Ai[i] = SQRT_FUN(diag);
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
